class Solution:
    def rearrangeSticks(self, n: int, k: int) -> int:
        import sys
        sys.setrecursionlimit(2 * n + 100)
        MOD = 10 ** 9 + 7

        @lru_cache(None)
        def f(i, j):
            if j == 0:
                return 1 if i == 0 else 0
            return (f(i - 1, j - 1) + (i - 1) * f(i - 1, j)) % MOD

        return f(n, k)

