        MOD = 10 ** 9 + 7
        dp = [0] * (k + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            ndp = [0] * (k + 1)
            for j in range(1, min(i, k) + 1):
                ndp[j] = (dp[j - 1] + (i - 1) * dp[j]) % MOD
            dp = ndp
        return dp[k]

