class Solution {
public:
    int rearrangeSticks(int n, int k) {
        const long long MOD = 1000000007LL;
        vector<long long> dp(k + 1, 0), ndp(k + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fill(ndp.begin(), ndp.end(), 0LL);
            int hi = min(i, k);
            for (int j = 1; j <= hi; ++j)
                ndp[j] = (dp[j - 1] + (long long)(i - 1) * dp[j]) % MOD;
            swap(dp, ndp);
        }
        return (int)dp[k];
    }
};

