class Solution {
    public int rearrangeSticks(int n, int k) {
        final long MOD = 1_000_000_007L;
        long[] dp = new long[k + 1], ndp = new long[k + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; ++i) {
            Arrays.fill(ndp, 0L);
            int hi = Math.min(i, k);
            for (int j = 1; j <= hi; ++j)
                ndp[j] = (dp[j - 1] + (long)(i - 1) * dp[j]) % MOD;
            long[] tmp = dp; dp = ndp; ndp = tmp;
        }
        return (int) dp[k];
    }
}

